public class ClasificadorNumeros {
    public static void main(String[] args) {
        int numero = -7;

        if (numero > 0) {
            System.out.println("The number " + numero + " is positive");
        } else if (numero < 0) {
            System.out.println("The number " + numero + " is negative");
        } else {
            System.out.println("The number is zero");
        }
    }
}

