solution:
public class CalculadoraIMC {
    public static void main(String[] args) {
        double peso = 72.0;
        double altura = 1.75;

        double imc = peso / (altura * altura);
        String categoria;

        if (imc < 18.5) {
            categoria = "Underweight";
        } else if (imc < 25) {
            categoria = "Normal";
        } else if (imc < 30) {
            categoria = "Overweight";
        } else {
            categoria = "Obesity";
        }

        System.out.printf("Weight: %.1f kg, Height: %.2f m%n", peso, altura);
        System.out.printf("BMI: %.1f - %s%n", imc, categoria);
    }
}

