solution:
public class ValidadorPassword {
    public static void main(String[] args) {
        String password = "Java1234@";
        int reglasCumplidas = 0;

        if (password.length() >= 8) reglasCumplidas++;

        boolean tieneMayuscula = false;
        boolean tieneNumero = false;
        boolean tieneEspecial = false;

        for (char c : password.toCharArray()) {
            if (Character.isUpperCase(c)) tieneMayuscula = true;
            if (Character.isDigit(c)) tieneNumero = true;
            if (c == '@' || c == '#' || c == '$') tieneEspecial = true;
        }

        if (tieneMayuscula) reglasCumplidas++;
        if (tieneNumero) reglasCumplidas++;
        if (tieneEspecial) reglasCumplidas++;

        String feedback;
        if (reglasCumplidas == 4) {
            feedback = "Secure password ✅";
        } else if (reglasCumplidas == 3) {
            feedback = "Moderate password ⚠️";
        } else if (reglasCumplidas >= 1) {
            feedback = "Weak password ❌";
        } else {
            feedback = "Invalid password 🚫";
        }

        System.out.println("Rules met: " + reglasCumplidas + "/4");
        System.out.println("Result: " + feedback);
    }
}
